import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
/**
 * What changed on this forum, and when — the "recently updated" list an app
 * store keeps. Read from storage/extension-manager/history.json (see History.php).
 */
export default class HistoryTab extends Component {
  view() {
    const history = this.attrs.history || [];
    if (!history.length) return m("div", {
      className: "ExtensionManager-empty"
    }, app.translator.trans('flarum-extension-manager.admin.sections.queue.none'));
    const names = {};
    (this.attrs.installed || []).forEach(e => names[e.package] = e.name);
    names['flarum/core'] = names['flarum/core'] || app.translator.trans('flarum-extension-manager.admin.sections.queue.flarum', {}, true);
    return m("ol", {
      className: "ExtensionManager-history"
    }, history.map(entry => {
      // The packages somebody asked for lead; what came along with them follows.
      const requested = entry.requested || [];
      const changes = [...(entry.changes || [])].sort((a, b) => Number(requested.includes(b.package)) - Number(requested.includes(a.package)));
      const when = dayjs(entry.at * 1000);
      return m("li", {
        key: entry.id,
        className: 'ExtensionManager-historyItem is-' + entry.state
      }, m("div", {
        className: "ExtensionManager-historyHead"
      }, m("span", {
        className: 'ExtensionManager-tag' + this.tone(entry.state)
      }, this.outcome(entry)), m("time", {
        datetime: when.toISOString(),
        title: when.format('LLLL')
      }, when.format('LLL'))), m("ul", {
        className: "ExtensionManager-historyChanges"
      }, changes.length ? changes.map(c => m("li", {
        key: c.package
      }, m("b", null, names[c.package] || c.package), " ", m("span", {
        className: "ExtensionManager-pkg"
      }, c.package), ' ', m("span", {
        className: "ExtensionManager-historyVersions"
      }, c.op === 'add' ? app.translator.trans('flarum-extension-manager.admin.sections.queue.new_version', {
        version: c.to
      }) : c.op === 'remove' ? app.translator.trans('flarum-extension-manager.admin.sections.queue.removed_version', {
        version: c.from
      }) : `${c.from} → ${c.to}`))) : m("li", null, requested.join(', ') || app.translator.trans('flarum-extension-manager.admin.sections.queue.nothing'))), entry.migrations ? m("div", {
        className: "ExtensionManager-historyNote"
      }, app.translator.trans('flarum-extension-manager.admin.sections.queue.migrations', {
        count: entry.migrations
      })) : null);
    }));
  }
  outcome(entry) {
    if (entry.state === 'rolled-back') return app.translator.trans('flarum-extension-manager.admin.sections.queue.statuses.rolled_back');
    if (entry.state === 'failed') return app.translator.trans('flarum-extension-manager.admin.sections.queue.statuses.failure');
    return entry.mode === 'install' ? app.translator.trans('flarum-extension-manager.admin.sections.queue.operations.extension_install') : entry.mode === 'remove' ? app.translator.trans('flarum-extension-manager.admin.sections.queue.operations.extension_remove') : app.translator.trans('flarum-extension-manager.admin.sections.queue.operations.extension_update');
  }
  tone(state) {
    return state === 'done' ? ' ExtensionManager-tag--ok' : state === 'failed' ? ' ExtensionManager-tag--warn' : ' ExtensionManager-tag--muted';
  }
}
flarum.reg.add('flarum-extension-manager', 'admin/components/HistoryTab', HistoryTab);